/* A guided attack circuit. Moving takes full control; ordinary held fire
   releases aligned ground payloads as well as the optional manual G control. */
static int bombing_ready(void){return journey_kind()!=ENV_BASE||ex.bombing.complete;}
static void bombing_enter(void){Bombing*b=&ex.bombing;*b=(Bombing){.active=1,.payload=6,.pathX=160,.pathY=220};static const int x[8]={110,220,135,190,80,135,190,245};for(int i=0;i<8;i++){int role=i<2?1:i<4?2:0,hp=role==2?8:6;b->targets[i]=(GroundTarget){hp,hp,x[i],i<4?45:115,role};}g.px=160*Q;player_y=220*Q;}
static int bombing_shielded(int i){if(ex.bombing.targets[i].role==1)return 0;return ex.bombing.targets[0].hp>0||ex.bombing.targets[1].hp>0;}
static int bombing_pass_tick74(void){Bombing*b=&ex.bombing;return b->timer+(b->stage==1?500:b->stage==2?600:b->stage==3?700:0);}
static void bombing_payload_step(void){Bombing*b=&ex.bombing;for(int n=0;n<12;n++){GroundPayload*p=b->bombs+n;if(!p->on)continue;p->age++;p->x+=p->vx;p->y+=p->vy;if(p->age>90||p->y<20*Q||p->x<0||p->x>320*Q){p->on=0;continue;}if(p->age<5)continue;for(int i=0;i<8;i++){GroundTarget*t=b->targets+i;if(t->hp<=0||absn(p->x/Q-t->x)>21||absn(p->y/Q-t->y)>18)continue;p->on=0;b->hits++;if(bombing_shielded(i)){pc_hit_sound(1,9,t->x);pc_impact(t->x,t->y,3);}else{t->hp=clamp(t->hp-3,0,t->maxHp);pc_torpedo_blast(t->x,t->y);pc_torpedo_sound(1,t->x);if(!t->hp){b->targetsDestroyed++;g.score+=350;if(t->role)ex.baseDamage++;salvage_add(t->x,t->y);salvage_add(t->x,t->y);burst(t->x,t->y,1);}}break;}}
 if(b->targetsDestroyed==8&&!b->cleared){b->cleared=b->complete=1;b->timer=bombing_pass_tick74();b->stage=0;b->angle=0;g.shield=100;for(int n=0;n<12;n++)b->bombs[n].on=0;}}
static void bombing_launch(void){Bombing*b=&ex.bombing;if(!b->launchRequested)return;b->launchRequested=0;if(b->stage||b->complete||b->cool||!b->payload)return;for(int n=0;n<12;n++)if(!b->bombs[n].on){b->bombs[n]=(GroundPayload){1,g.px,player_y-9*Q,0,-1000,0};b->payload--;b->cool=35;pc_torpedo_sound(0,g.px/Q);return;}}
static void bombing_fire74(void){Bombing*b=&ex.bombing;if(!b->active||b->complete||b->stage||b->cool||!b->payload)return;int closest=-1,y=-1000;for(int i=0;i<8;i++){GroundTarget*t=b->targets+i;if(t->hp>0&&absn(t->x-g.px/Q)<=21&&t->y<player_y/Q-24&&t->y>=24&&t->y>y){closest=i;y=t->y;}}if(closest>=0&&!bombing_shielded(closest))b->launchRequested=1;}
static float bombing_ease(float x){return x*x*(3-2*x);}
static void bombing_step(void){Bombing*b=&ex.bombing;if(!b->active)return;b->worldTick++;b->timer++;int groundTime=bombing_pass_tick74();for(int i=0;i<8;i++)b->targets[i].y=(i<4?45:115)+(groundTime-100)*45/100;if(b->complete)return;if(b->cool)b->cool--;b->angle=0;
 if(b->stage==0){b->pathX=160+(sn(b->timer/2+b->pass*37)*70>>10);b->pathY=220-(sn(b->timer/3)*15>>10);if(!b->manual){g.px=b->pathX*Q;player_y=b->pathY*Q;}for(int i=0;i<8;i++){GroundTarget*t=b->targets+i;t->y=(i<4?45:115)+(b->timer-100)*45/100;if(t->hp>0&&t->role==0&&b->timer>100&&b->timer%100==i*7&&t->y>24&&t->y<220)aim(t->x*Q,t->y*Q,300);}bombing_launch();if(b->timer>=500){b->startX=g.px/Q;b->startY=player_y/Q;b->stage=1;b->timer=0;for(int n=0;n<MAXB;n++)g.bullets[n].on=0;}}
 else if(b->stage==1){float u=bombing_ease(clamp(b->timer,0,100)/100.0f);if(!b->manual){g.px=(int)((b->startX+(160-b->startX)*u)*Q);player_y=(int)((b->startY+(100-b->startY)*u)*Q);}g.shield=20;b->launchRequested=0;if(b->timer>=100){b->stage=2;b->timer=0;}}
 else if(b->stage==2){float u=clamp(b->timer,0,100)/100.0f;if(!b->manual){g.px=(int)((160+sinf(u*3.14159265359f)*60)*Q);player_y=(int)((140-cosf(u*3.14159265359f)*40)*Q);}g.shield=20;b->launchRequested=0;if(b->timer>=100){b->pass++;b->stage=3;b->timer=0;b->payload=6;b->cool=0;b->offset=0;b->startX=g.px/Q;b->startY=player_y/Q;}}
 else{float u=bombing_ease(clamp(b->timer,0,75)/75.0f);int target=160+(sn(b->pass*37)*70>>10);if(!b->manual){g.px=(int)((b->startX+(target-b->startX)*u)*Q);player_y=(int)((b->startY+(220-b->startY)*u)*Q);}g.shield=20;b->launchRequested=0;if(b->timer>=75){b->stage=0;b->timer=0;b->pathX=target;b->pathY=220;if(b->cleared){b->complete=1;g.shield=100;}}}
 bombing_payload_step();
}
